/**
 * Admin Service — Business logic for admin operations.
 * Generated by BackendForge
 */
const { ApiError } = require('../middleware/error-handler.middleware');
const { Order, OrderItem, User, Product, AuditLog } = require('../models');
const { sequelize } = require('../config/database');
const { Op, fn, col, literal } = require('sequelize');

const adminService = {
  /**
   * Dashboard stats — revenue, order counts, etc.
   */
  async getDashboardStats() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [totalOrders, todayOrders, totalRevenue, pendingShipments, totalCustomers, totalProducts, recentCancellations] = await Promise.all([
      Order.count(),
      Order.count({ where: { createdAt: { [Op.gte]: today } } }),
      Order.sum('totalAmount', { where: { paymentStatus: 'paid' } }),
      Order.count({ where: { shippingStatus: { [Op.in]: ['pending', 'confirmed', 'processing'] }, isCancelled: false } }),
      User.count({ where: { role: 'customer' } }),
      Product.count({ where: { isActive: true } }),
      Order.count({ where: { isCancelled: true } }),
    ]);

    return {
      totalOrders,
      todayOrders,
      totalRevenue: totalRevenue || 0,
      pendingShipments,
      totalCustomers,
      totalProducts,
      recentCancellations,
    };
  },

  /**
   * Get admin's own account details.
   */
  async getAdminAccount(adminId) {
    const admin = await User.findByPk(adminId);
    const recentActions = await AuditLog.findAll({
      where: { adminId },
      order: [['createdAt', 'DESC']],
      limit: 10,
    });
    if (!admin) throw ApiError.notFound('Admin not found');

    return {
      profile: admin,
      recentActions,
    };
  },

  /**
   * Get all orders with full customer details (name, email, phone, payment, shipping).
   */
  async getAllOrders(pagination, filters = {}) {
    const { offset, limit, sort, order } = pagination;
    const where = {};
    if (filters.status) where.shippingStatus = filters.status;
    if (filters.paymentStatus) where.paymentStatus = filters.paymentStatus;
    if (filters.search) {
      where[Op.or] = [
        { orderNumber: { [Op.iLike]: `%${filters.search}%` } },
      ];
    }

    const { count: total, rows: orders } = await Order.findAndCountAll({
      where,
      include: [
        { model: User, as: 'user', attributes: ['id', 'name', 'email', 'phone'] },
        { model: OrderItem, as: 'items' },
      ],
      order: [[sort, order]],
      offset,
      limit,
    });

    return { orders, total };
  },

  /**
   * Update order shipping status — auto-reflects in customer's account.
   */
  async updateOrderStatus(orderId, statusData, adminUser) {
    const { shippingStatus, trackingNumber, carrier, estimatedDelivery, adminNotes } = statusData;

    const order = await Order.findByPk(orderId);

    if (!order) throw ApiError.notFound('Order not found');
    if (order.isCancelled) throw ApiError.badRequest('Cannot update cancelled order');

    const updates = { shippingStatus };
    if (trackingNumber) updates.trackingNumber = trackingNumber;
    if (carrier) updates.carrier = carrier;
    if (estimatedDelivery) updates.estimatedDelivery = estimatedDelivery;
    if (adminNotes) updates.adminNotes = adminNotes;

    await order.update(updates);

    // The updated status is now visible to the customer via GET /api/users/orders
    // and GET /api/orders/:id — no extra work needed, it's the same database record.

    return order;
  },

  /**
   * Get all cancelled orders.
   */
  async getCancellations(pagination) {
    const { offset, limit, sort, order } = pagination;
    const { count: total, rows: orders } = await Order.findAndCountAll({
      where: { isCancelled: true },
      include: [{ model: User, as: 'user', attributes: ['id', 'name', 'email', 'phone'] }],
      order: [['cancelledAt', 'DESC']],
      offset, limit,
    });
    return { orders, total };
  },

  /**
   * Get customer list.
   */
  async getCustomers(pagination, search) {
    const { offset, limit, sort, order } = pagination;
    const where = { role: 'customer' };
    if (search) {
      where[Op.or] = [
        { name: { [Op.iLike]: `%${search}%` } },
        { email: { [Op.iLike]: `%${search}%` } },
        { phone: { [Op.iLike]: `%${search}%` } },
      ];
    }
    const { count: total, rows: customers } = await User.findAndCountAll({
      where,
      order: [[sort, order]],
      offset, limit,
    });
    return { customers, total };
  },

  /**
   * Get audit log.
   */
  async getAuditLog(pagination) {
    const { offset, limit } = pagination;
    const { count: total, rows: logs } = await AuditLog.findAndCountAll({
      order: [['createdAt', 'DESC']],
      offset, limit,
    });
    return { logs, total };
  },
};

module.exports = adminService;
